    [1303503] = { en = "Expels the remaining mana in an elemental to an area that restores $1303505s1 mana every $1303505t1 second to nearby creatures.", description = "Espelle il mana rimanente da un elementale in un'area, ripristinando $1303505s1 mana ogni $1303505t1 secondo alle creature vicine." },
