    [1303509] = { en = "Spread the incense over the southern cliff of Hunter Rise.", description = "Spargi l'incenso sulla scogliera meridionale di Altura del Cacciatore." },
    [1303543] = { en = "Raise a Scarlet Banner at a campsite. Requires a Campfire nearby.", description = "Innalza uno Stendardo Scarlatto in un accampamento. Richiede un falò nelle vicinanze." },
    [1303598] = { en = "Transforms nearby enemies into an animal, forcing it to wander around for up to $d. While wandering, the polymorph cannot attack or cast spells.", description = "Trasforma i nemici vicini in animali, costringendoli a vagare per un massimo di $d. Mentre vagano, i bersagli non possono attaccare né lanciare incantesimi." },
    [1303599] = { en = "While channeling this spell, your mana regenerates at an accelerated rate. Lasts $d.", description = "Durante il lancio di questo incantesimo, il mana si rigenera a velocità accelerata. Dura $d." },
    [1303634] = { en = "Cures the target of ailments.", description = "Cura il bersaglio dai suoi malanni." },
    [1303755] = { en = "Toss a Hearthstone to a wounded Slave Worker.", description = "Lancia una Pietra del Ritorno a un Lavoratore Schiavo ferito." },
    [1303869] = { en = "Toss a Hearthstone to a wounded Slave Worker, after knocking some sense into them.", description = "Lancia una Pietra del Ritorno a un Lavoratore Schiavo ferito, dopo averlo fatto rinsavire." },
    [1304452] = { en = "Increases critical chance of spells and attacks by $s1%, increases Attack Power by $s2, and increases spell damage and healing by up to $s4. Lasts $d.", description = "Aumenta del $s1% la probabilità di critico degli incantesimi e degli attacchi, aumenta la potenza d'attacco di $s2 e aumenta fino a $s4 i danni degli incantesimi e le cure. Dura $d." },
    [1304751] = { en = "Chance for a critical hit with all spells and attacks increased by $s1%.", description = "La probabilità di colpo critico con tutti gli incantesimi e gli attacchi aumenta del $s1%." },
    [1305116] = { en = "Throw the loosely tied pouch of tomb dust into The Great Sea.", description = "Lancia la borsa legata alla bell'e meglio di polvere tombale nel Grande Mare." },
    [1305400] = { en = "Open a difficult lock.", description = "Apri una serratura difficile." },
    [1305416] = { en = "Deceive enemies with a look-alike, causing nearby creatures to attack it for $d.", description = "Inganna i nemici con un sosia, facendo sì che le creature vicine lo attacchino per $d." },
    [1305424] = { en = "Restores $1305426s1 Mana when you kill a Dragonkin that gives experience. This effect cannot occur more than once every $proccooldown sec.", description = "Ripristina $1305426s1 mana quando uccidi un Dracoide che fornisce esperienza. Questo effetto può verificarsi al massimo una volta ogni $proccooldown sec." },
    [1305426] = { en = "$s1 Mana restored.", description = "Ripristina $s1 mana." },
    [1305718] = { en = "While in combat, your healing spells have a chance to call forth an Onyxia Whelpling to protect you in battle for $d.", description = "In combattimento, i tuoi incantesimi di cura hanno una probabilità di evocare un Cucciolo di Onyxia che ti proteggerà in battaglia per $d." },
    [1305732] = { en = "Healing spells have a chance to call forth an Onyxia Whelpling to protect you in battle for $1305718d.", description = "Gli incantesimi di cura hanno una probabilità di evocare un Cucciolo di Onyxia che ti proteggerà in battaglia per $1305718d." },
    [1305855] = { en = "Kargra's eyes see beyond the mortal realms, reducing her chance to hit with attacks by $S1%.", description = "Gli occhi di Kargra vedono oltre i regni mortali, riducendo la sua probabilità di colpire con gli attacchi del $S1%." },
    [1306076] = { en = "Movement speed Increased by $s1% in Forest and Grassland areas.", description = "Velocità di movimento aumentata del $s1% nelle aree di foresta e prateria." },
    [1306126] = { en = "Allows the miner to smelt a chunk of heavy thorium ore into a heavy thorium bar. Smelting heavy thorium requires a molten foundry.", description = "Permette al minatore di fondere un pezzo di minerale di torio pesante in una barra di torio pesante. Per fondere il torio pesante è necessaria una fornace fusa." },
    [1306158] = { en = "Increases healing done by up to $s1 and damage done by up to $s2 for all magical spells and effects. This effect is doubled at Night.", description = "Aumenta le cure effettuate fino a $s1 e i danni inflitti fino a $s2 con tutti gli incantesimi ed effetti magici. Questo effetto raddoppia di notte." },
    [1306267] = { en = "Place a Traveler's Sign that lasts for 1 min. A message can be written on the sign, causing it to last for 1 hour and making it visible to other players.", description = "Colloca un'insegna da viaggiatore che dura 1 min. È possibile scrivere un messaggio sull'insegna, facendola durare 1 ora e rendendola visibile agli altri giocatori." },
    [1306429] = { en = "Increases the critical strike chance of your Holy Shock spell by $s1%.", description = "Aumenta del $s1% la probabilità di colpo critico del tuo incantesimo Folgore Sacra." },
    [1306433] = { en = "Increases the Block Value of your shield by $1306749s1% while Holy Shield is active.", description = "Aumenta del $1306749s1% il valore di blocco dello scudo mentre lo Scudo Sacro è attivo." },
    [1306438] = { en = "Knocks the target back, reducing threat to zero.", description = "Respinge il bersaglio, azzerando la minaccia." },
    [1306448] = { en = "Increases the critical strike chance of your Lessing Healing Wave spell by $s1%.", description = "Aumenta del $s1% la probabilità di colpo critico del tuo incantesimo Ondata Curativa Lessing." },
    [1306459] = { en = "While in Bear Form, Dire Bear Form, or Moonkin Form, you gain additional base Armor equal to ${$m1*100}% of your Defense skill.", description = "In Forma d'Orso, Forma d'Orso Tenebroso o Forma di Lunagufo, ottieni armatura base aggiuntiva pari al ${$m1*100}% della tua abilità Difesa." },
    [1306483] = { en = "Your Lacerate hits have a $h% chance to reset the cooldown on Mangle (Bear).", description = "I tuoi colpi di Lacerazione hanno una probabilità del $h% di azzerare il tempo di recupero di Devastazione (Orso)." },
    [1306488] = { en = "Reduces the cooldown on your Swiftmend spell by ${$m1/-1000} sec.", description = "Riduce il tempo di recupero del tuo incantesimo Rapida Guarigione di ${$m1/-1000} sec." },
    [1306572] = { en = "Reduces your target's Fire resistance by $s1.", description = "Riduce di $s1 la resistenza al Fuoco del bersaglio." },
    [1306580] = { en = "Reduces your target's Frost resistance by $s1.", description = "Riduce di $s1 la resistenza al Gelo del bersaglio." },
    [1306607] = { en = "Reduces the duration of all Disease effects applied to you by $m1%.", description = "Riduce del $m1% la durata di tutti gli effetti di malattia applicati su di te." },
    [1306622] = { en = "Deal $s1 Nature damage to the target and their nearest ally. Deals $s2 times as much damage to Plants and Undead.", description = "Infligge $s1 danni da Natura al bersaglio e al suo alleato più vicino. Infligge danni moltiplicati per $s2 a piante e Non Morti." },
    [1306628] = { en = "Scoop up snow from South Gate Pass into the ceramic jar.", description = "Raccogli la neve dal Passo del Cancello Sud e mettila nel vaso di ceramica." },
    [1306632] = { en = "Restores $s1 Mana per 5 sec in Wasteland areas.", description = "Ripristina $s1 mana ogni 5 sec nelle aree desolate." },
    [1306672] = { en = "Restores $s1 Health per 5 sec in Swamp areas.", description = "Ripristina $s1 salute ogni 5 sec nelle aree paludose." },
    [1306676] = { en = "Deals $1306675s1 damage whenever you block. Damage range and school change with the Season.", description = "Infligge $1306675s1 danni ogni volta che blocchi. L'intervallo e la scuola dei danni cambiano con la stagione." },
    [1306677] = { en = "Deal $s1 Nature damage.", description = "Infligge $s1 danni da Natura." },
    [1306679] = { en = "Deal $s1 Frost damage.", description = "Infligge $s1 danni da Gelo." },
    [1306681] = { en = "Improves your chance to hit with off-hand attacks by ${$s1}.1%.", description = "Migliora del ${$s1}.1% la probabilità di colpire con gli attacchi con la mano secondaria." },
    [1306682] = { en = "Misses with Rumination have a $h% chance to strike again.", description = "I colpi mancati con Rimuginio hanno una probabilità del $h% di colpire di nuovo." },
    [1306686] = { en = "Increases melee attack range by $s2 yards.", description = "Aumenta di $s2 iarde la portata degli attacchi in mischia." },
    [1306689] = { en = "Damage that would kill you instead reduces you to 1 Health and grants immunity to damage for $1306691d. Occurs once every $1306690d.", description = "I danni che ti ucciderebbero ti riducono invece a 1 Salute e ti rendono immune ai danni per $1306691d. Si verifica una volta ogni $1306690d." },
    [1306693] = { en = "Bring to the Hillsbrad Town Hall's bookkeeping table. ", description = "Porta al tavolo della contabilità del Municipio di Hillsbrad. " },
    [1306695] = { en = "Deliver to the bottom floor of Dun Garok.", description = "Consegna al piano inferiore di Dun Garok." },
    [1306699] = { en = "Increases healing done by up to $s1 and damage done by up to $s2 for all magical spells and effects while in Mountainous areas.", description = "Aumenta le cure effettuate fino a $s1 e i danni inflitti fino a $s2 con tutti gli incantesimi ed effetti magici nelle aree montuose." },
    [1306700] = { en = "Open a vial and place on the ground at a high vantage point.", description = "Apri una fiala e posizionala a terra in un punto sopraelevato." },
    [1306759] = { en = "Reduces ranged damage taken by $s1.", description = "Riduce di $s1 i danni a distanza subiti." },
    [1306765] = { en = "Strike your ranged target with a Storm Shot for $s1 Nature damage.", description = "Colpisce il bersaglio a distanza con un Colpo della Tempesta, infliggendo $s1 danni da Natura." },
    [1306786] = { en = "Judgement casts against Beasts reduce the remaining cooldown of Holy Strike by ${$s1/-1000}.1 sec.", description = "I lanci di Giudizio contro le Bestie riducono il tempo di recupero rimanente di Colpo Sacro di ${$s1/-1000}.1 sec." },
    [1306794] = { en = "Elune empowers the Huntress with rage inflicting $s1 Arcane damage to enemies within $a yards and inflicting $1306811s1 Arcane damage every $t2 sec.", description = "Elune infonde potere alla Cacciatrice con una furia che infligge $s1 danni da Arcano ai nemici entro $a metri e infligge $1306811s1 danni da Arcano ogni $t2 sec." },
    [1306798] = { en = "You have $sk134/$<sc> skill in $@spellname1306798.\r\n\r\nLevel $PL target:\r\nHit, Dodge, and Parry: ${$<hdp>}.1%\r\nCritical Hit: ${$<cr>}.1%\r\nGlancing Blow Penalty: ${$<gp>}%\r\nGlancing Blow Chance: ${$<gc>}%\r\n$@expandkey[\r\nLevel ${$PL+1} target:\r\nHit, Dodge, and Parry: ${$<hdp1>}.1%\r\nCritical Hit: ${$<cr1>}.1%\r\nGlancing Blow Penalty: ${$<gp1>}%\r\nGlancing Blow Chance: ${$<gc1>}%\r\n\r\nLevel ${$PL+2} target:\r\nHit, Dodge, and Parry: ${$<hdp2>}.1%\r\nCritical Hit: ${$<cr2>}.1%\r\nGlancing Blow Penalty: ${$<gp2>}%\r\nGlancing Blow Chance: ${$<gc2>}%\r\n\r\nLevel ${$PL+3} target:\r\nHit, Dodge, and Parry: ${$<hdp3>}.1%\r\nCritical Hit: ${$<cr3>}.1%\r\nGlancing Blow Penalty: ${$<gp3>}%\r\nGlancing Blow Chance: ${$<gc3>)}%\r\n\r\n$@spelldesc1302929\r\n]", description = "Hai $sk134/$<sc> abilità in $@spellname1306798.\r\n\r\nBersaglio di livello $PL:\r\nColpo, schivata e parata: ${$<hdp>}.1%\r\nColpo critico: ${$<cr>}.1%\r\nPenalità colpo di striscio: ${$<gp>}%\r\nProbabilità colpo di striscio: ${$<gc>}%\r\n$@expandkey[\r\nBersaglio di livello ${$PL+1}:\r\nColpo, schivata e parata: ${$<hdp1>}.1%\r\nColpo critico: ${$<cr1>}.1%\r\nPenalità colpo di striscio: ${$<gp1>}%\r\nProbabilità colpo di striscio: ${$<gc1>}%\r\n\r\nBersaglio di livello ${$PL+2}:\r\nColpo, schivata e parata: ${$<hdp2>}.1%\r\nColpo critico: ${$<cr2>}.1%\r\nPenalità colpo di striscio: ${$<gp2>}%\r\nProbabilità colpo di striscio: ${$<gc2>}%\r\n\r\nBersaglio di livello ${$PL+3}:\r\nColpo, schivata e parata: ${$<hdp3>}.1%\r\nColpo critico: ${$<cr3>}.1%\r\nPenalità colpo di striscio: ${$<gp3>}%\r\nProbabilità colpo di striscio: ${$<gc3>)}%\r\n\r\n$@spelldesc1302929\r\n]" },
    [1306900] = { en = "Improves your chance to get a critical strike or heal by ${$s1}.1% against targets below $s2% Health.", description = "Aumenta di ${$s1}.1% la probabilità di infliggere un colpo critico o di effettuare una cura critica contro i bersagli con meno del $s2% di Salute." },
    [1306905] = { en = "Increases healing done by up to $s1 and damage done by up to $s2 for all magical spells and effects while in Snowy areas.", description = "Aumenta le cure effettuate fino a $s1 e i danni inflitti fino a $s2 con tutti gli incantesimi ed effetti magici nelle aree innevate." },
    [1306907] = { en = "Permanently increase the Defense Skill by $ec1 and the Stamina value by $ec2 of an item worn on the chest, legs, hands or feet. Only usable on items level $ecim and above.", description = "Aumenta permanentemente di $ec1 l'abilità Difesa e di $ec2 il valore di Tempra di un oggetto indossato sul torso, sulle gambe, sulle mani o sui piedi. Utilizzabile solo sugli oggetti di livello $ecim o superiore." },
    [1306908] = { en = "Movement speed Increased by $s1% in Snowy areas.", description = "Velocità di movimento aumentata del $s1% nelle aree innevate." },
    [1306933] = { en = "Blasts a target for $s1 Frost damage. In Snowy areas, also deals an additional $1306934s1 Fire damage.", description = "Colpisce un bersaglio infliggendo $s1 danni da Gelo. Nelle aree innevate infligge anche $1306934s1 danni aggiuntivi da Fuoco." },
    [1306956] = { en = "Periodically summons the aid of the Blackthorne Pact.", description = "Evoca periodicamente l'aiuto del Patto di Blackthorne." },
    [1307007] = { en = "Charged with lightning, dealing $1307008S1 nature damage to random nearby locations every $t1 sec.", description = "Caricato di fulmini, infligge $1307008S1 danni da Natura in punti casuali nelle vicinanze ogni $t1 sec." },
    [1307008] = { en = "$@spelldesc1307007", description = "$@spelldesc1307007" },
    [1307014] = { en = "Increases your effective stealth detection level by ${$s1/5} for $d.", description = "Aumenta il tuo livello effettivo di individuazione della furtività di ${$s1/5} per $d." },
    [1307019] = { en = "Target's movement slowed and time between attacks increased.", description = "Movimento del bersaglio rallentato e intervallo tra gli attacchi aumentato." },
    [1307050] = { en = "Attaches a permanent scope to a bow, gun, or crossbow that increases its critical strike chance by $s2%.", description = "Applica permanentemente un mirino a un arco, una pistola o una balestra, aumentando del $s2% la probabilità di colpo critico." },
    [1307066] = { en = "$@spelldesc1307067", description = "$@spelldesc1307067" },
    [1307067] = { en = "In a flash of steel the caster whirls their weapons in an attack that inflicts normal damage plus $1307066s1 to all players within $1307066A1 yards.", description = "In un lampo d'acciaio, l'incantatore fa roteare le proprie armi in un attacco che infligge danni normali più $1307066s1 a tutti i giocatori entro $1307066A1 metri." },
    [1307172] = { en = "Places an Alchemy Laboratory usable for recipes that require it, and provides all of the benefits of a Mana Well. Requires a Campfire nearby. \r\n\r\nMay be placed over a Mana Well to replace it.\r\n All camping features share a cooldown of $1308027d.", description = "Piazza un Laboratorio di Alchimia utilizzabile per le ricette che lo richiedono e fornisce tutti i benefici di un Pozzo di Mana. Richiede un Falò nelle vicinanze. \r\n\r\nPuò essere piazzato sopra un Pozzo di Mana per sostituirlo.\r\n Tutte le strutture da accampamento condividono un tempo di recupero di $1308027d." },
    [1307174] = { en = "Places an Anarchist's Workbench usable for recipes that require it. Requires a Campfire nearby. All camping features share a cooldown of $1308027d.", description = "Piazza un Banco da lavoro anarchico utilizzabile per le ricette che lo richiedono. Richiede un Falò nelle vicinanze. Tutte le strutture da accampamento condividono un tempo di recupero di $1308027d." },
    [1307175] = { en = "Places an anvil, and provides all of the benefits of a Sharpening Wheel. Requires a Campfire nearby. \r\n\r\nMay be placed over a Sharpening Wheel to replace it. All camping features share a cooldown of $1308027d.", description = "Piazza un'incudine e fornisce tutti i benefici di una Mola per affilare. Richiede un Falò nelle vicinanze. \r\n\r\nPuò essere piazzata sopra una Mola per affilare per sostituirla. Tutte le strutture da accampamento condividono un tempo di recupero di $1308027d." },
    [1307176] = { en = "Places an Arcane Forge usable for recipes that require it, and provides all the benefits of an Enchanted Lute. Requires a Campfire nearby. \r\n\r\nMay be placed over an Enchanted Lute to replace it. All camping features share a cooldown of $1308027d.", description = "Piazza una Forgia Arcana utilizzabile per le ricette che la richiedono e fornisce tutti i benefici di un Liuto incantato. Richiede un Falò nelle vicinanze. \r\n\r\nPuò essere piazzata sopra un Liuto incantato per sostituirlo. Tutte le strutture da accampamento condividono un tempo di recupero di $1308027d." },
    [1307208] = { en = "Shock casts against Undead reduce the remaining cooldown of Stormstrike by ${$s1/-1000}.1 sec.", description = "I lanci di Folgore contro i Non Morti riducono il tempo di recupero rimanente di Assalto della Tempesta di ${$s1/-1000}.1 sec." },
    [1307223] = { en = "Places an Arcane Salvager that enables more efficient disenchanting, and provides all the benefits of an Enchanted Lute. Requires a Campfire nearby. \r\n\r\nMay be placed over an Enchanted Lute to replace it.\r\n All camping features share a cooldown of $1308027d.", description = "Piazza un Recuperatore Arcano che consente di disincantare con maggiore efficienza e fornisce tutti i benefici di un Liuto incantato. Richiede un Falò nelle vicinanze. \r\n\r\nPuò essere piazzato sopra un Liuto incantato per sostituirlo.\r\n Tutte le strutture da accampamento condividono un tempo di recupero di $1308027d." },
    [1307226] = { en = "Places an Iron Oven required for the most advanced cooking recipes. Requires a Cooking Fire nearby. All camping features share a cooldown of $1308027d.", description = "Piazza un Forno di ferro, necessario per le ricette di cucina più avanzate. Richiede un Fuoco da cucina nelle vicinanze. Tutte le strutture da accampamento condividono un tempo di recupero di $1308027d." },
    [1307227] = { en = "Builds a basic campfire that allows cooking and the placement of up to $s1 additional camp features. Players sitting or crafting nearby for $1229739d will gain benefits from other camp features.", description = "Costruisce un falò base che consente di cucinare e piazzare fino a $s1 strutture da accampamento aggiuntive. I giocatori seduti o intenti a creare nelle vicinanze per $1229739d otterranno i benefici delle altre strutture da accampamento." },
    [1307229] = { en = "Assembles a camp chair that allows you and others sitting nearby to gain $1229519s1% increased critical strike chance with all spells and attacks, exclusive with Moonkin Aura.\r\n\r\nRequires a Campfire nearby. All camping features share a cooldown of $1308027d.", description = "Monta una sedia da accampamento che permette a te e agli altri seduti nelle vicinanze di ottenere un aumento del $1229519s1% della probabilità di colpo critico con tutti gli incantesimi e gli attacchi, incompatibile con Aura del Silvano.\r\n\r\nRichiede un Falò nelle vicinanze. Tutte le strutture da accampamento condividono un tempo di recupero di $1308027d." },
    [1307230] = { en = "Builds a tent that allows you and others sitting nearby to increase Rested experience to $s2% of a level. No effect if Rested experience already exceeds that value.\r\n\r\nRequires a Campfire nearby. All camping features share a cooldown of $1308027d.", description = "Monta una tenda che permette a te e agli altri seduti nelle vicinanze di aumentare l'esperienza Riposato fino al $s2% di un livello. Non ha effetto se l'esperienza Riposato supera già tale valore.\r\n\r\nRichiede un Falò nelle vicinanze. Tutte le strutture da accampamento condividono un tempo di recupero di $1308027d." },
    [1307234] = { en = "Summons an enchanted lute that allows you and others sitting nearby to gain $?$PL<10[28]?$PL<20[71]?$PL<30[114]?$PL<40[163]?$PL<50[211]?$PL<60[260][$1230653s1 ] increase to Armor$?$PL<10[]?$PL<30[ and ][, ]$?$PL>59[$1230653s2]?$PL>49[12]?$PL>39[9]?$PL>29[7]?$PL>19[4]?$PL>9[2][]$?$PL>9[ increase to all stats][]$?$PL>59[, and $1230653s3]?$PL>49[, and 16]?$PL>39[, and 12]?$PL>29[, and 6][]$?$PL>29[ increase to all resistances][], exclusive with Mark of the Wild.\r\n\r\nRequires a Campfire nearby. All camping features share a cooldown of $1308027d.", description = "Evoca un liuto incantato che permette a te e agli altri seduti nelle vicinanze di ottenere $?$PL<10[28]?$PL<20[71]?$PL<30[114]?$PL<40[163]?$PL<50[211]?$PL<60[260][$1230653s1 ] in più all'armatura$?$PL<10[]?$PL<30[ e ][, ]$?$PL>59[$1230653s2]?$PL>49[12]?$PL>39[9]?$PL>29[7]?$PL>19[4]?$PL>9[2][]$?$PL>9[ in più a tutte le statistiche][]$?$PL>59[, e $1230653s3]?$PL>49[, e 16]?$PL>39[, e 12]?$PL>29[, e 6][]$?$PL>29[ in più a tutte le resistenze][], incompatibile con Marchio della Natura.\r\n\r\nRichiede un Falò nelle vicinanze. Tutte le strutture da accampamento condividono un tempo di recupero di $1308027d." },
    [1307237] = { en = "Builds an expert campfire that allows cooking and the placement of up to $s1 additional camp features. Players sitting or crafting nearby for $1229739d will gain benefits from other camp features.", description = "Costruisce un falò esperto che consente di cucinare e piazzare fino a $s1 strutture da accampamento aggiuntive. I giocatori seduti o intenti a creare nelle vicinanze per $1229739d otterranno i benefici delle altre strutture da accampamento." },
    [1307239] = { en = "Unrolls a banner that allows you and others members of the Alliance sitting nearby to gain $?$PL<40[14]?$PL<50[19]?$PL<60[27][$1229718s1] increased Spirit, exclusive with Divine Spirit.\r\n\r\nRequires a Campfire nearby. All camping features share a cooldown of $1308027d.", description = "Srotola uno stendardo che permette a te e agli altri membri dell'Alleanza seduti nelle vicinanze di ottenere $?$PL<40[14]?$PL<50[19]?$PL<60[27][$1229718s1] in più allo Spirito, incompatibile con Spirito Divino.\r\n\r\nRichiede un Falò nelle vicinanze. Tutte le strutture da accampamento condividono un tempo di recupero di $1308027d." },
    [1307240] = { en = "Unrolls a banner that allows you and others members of the Horde sitting nearby to gain $?$PL<40[14]?$PL<50[19]?$PL<60[27][$1229718s1] increased Spirit, exclusive with Divine Spirit.\r\n\r\nRequires a Campfire nearby. All camping features share a cooldown of $1308027d.", description = "Srotola uno stendardo che permette a te e agli altri membri dell'Orda seduti nelle vicinanze di ottenere $?$PL<40[14]?$PL<50[19]?$PL<60[27][$1229718s1] in più allo Spirito, incompatibile con Spirito Divino.\r\n\r\nRichiede un Falò nelle vicinanze. Tutte le strutture da accampamento condividono un tempo di recupero di $1308027d." },
    [1307242] = { en = "Places a fermenter that allows the creation of certain reagents, and provides all of the benefits of a Mana Well. Requires a Campfire nearby. May be placed over a Mana Well to replace it. All camping features share a cooldown of $1308027d.", description = "Piazza un fermentatore che consente di creare alcuni reagenti e fornisce tutti i benefici di un Pozzo di Mana. Richiede un Falò nelle vicinanze. Può essere piazzato sopra un Pozzo di Mana per sostituirlo. Tutte le strutture da accampamento condividono un tempo di recupero di $1308027d." },
    [1307243] = { en = "Places a Field Guide that allows players to read it and gain Track Beasts, and provides all the benefits of a Camp Chair. Requires a Campfire nearby. \r\n\r\nMay be placed over a Camp Chair to replace it.\r\n All camping features share a cooldown of $1308027d.", description = "Piazza una Guida da campo che permette ai giocatori di leggerla e ottenere Tracciare Bestie, e fornisce tutti i benefici di una Sedia da accampamento. Richiede un Falò nelle vicinanze. \r\n\r\nPuò essere piazzata sopra una Sedia da accampamento per sostituirla.\r\n Tutte le strutture da accampamento condividono un tempo di recupero di $1308027d." },
    [1307244] = { en = "Unpacks a first aid kit that allows you and others sitting nearby to gain $?$PL<12[3]?$PL<24[8]?$PL<36[21]?$PL<48[34]?$PL<60[45][$1230124s1] increased Stamina, exclusive with Power Word: Fortitude.\r\n\r\nRequires a Campfire nearby. All camping features share a cooldown of $1308027d.", description = "Disimballa un kit di pronto soccorso che permette a te e agli altri seduti nelle vicinanze di ottenere $?$PL<12[3]?$PL<24[8]?$PL<36[21]?$PL<48[34]?$PL<60[45][$1230124s1] in più alla Tempra, incompatibile con Parola del Potere: Fermezza.\r\n\r\nRichiede un Falò nelle vicinanze. Tutte le strutture da accampamento condividono un tempo di recupero di $1308027d." },
    [1307245] = { en = "Places a small fish bowl that allows you and others sitting nearby to gain $1230098s1% increased stats, exclusive with Blessing of Kings.\r\n\r\nRequires a Campfire nearby. All camping features share a cooldown of $1308027d.", description = "Piazza una piccola boccia per pesci che permette a te e agli altri seduti nelle vicinanze di ottenere un aumento del $1230098s1% alle statistiche, incompatibile con Benedizione dei Re.\r\n\r\nRichiede un Falò nelle vicinanze. Tutte le strutture da accampamento condividono un tempo di recupero di $1308027d." },
    [1307246] = { en = "Places a Fishing Hut that grants the ability to catch rare fish for $1280342d, Fishing Skill lures, and provides all of the benefits of a Fish Bowl. Requires a Campfire nearby. \r\n\r\nMay be placed over a Fish Bowl to replace it.\r\n All camping features share a cooldown of $1308027d.", description = "Piazza una Capanna da pesca che consente di catturare pesci rari per $1280342d e fornisce esche per l'abilità di Pesca e tutti i benefici di una Boccia per pesci. Richiede un Falò nelle vicinanze. \r\n\r\nPuò essere piazzata sopra una Boccia per pesci per sostituirla.\r\n Tutte le strutture da accampamento condividono un tempo di recupero di $1308027d." },
    [1307247] = { en = "Places a Fishing Rack that grants the ability to catch uncommon fish for $1280341d, Fishing Skill lures, and provides all of the benefits of a Fish Bowl. Requires a Campfire nearby. \r\n\r\nMay be placed over a Fish Bowl to replace it. All camping features share a cooldown of $1308027d.", description = "Piazza un Banco da pesca che consente di catturare pesci non comuni per $1280341d e fornisce esche per l'abilità di Pesca e tutti i benefici di una Boccia per pesci. Richiede un Falò nelle vicinanze. \r\n\r\nPuò essere piazzato sopra una Boccia per pesci per sostituirla. Tutte le strutture da accampamento condividono un tempo di recupero di $1308027d." },
    [1307248] = { en = "Places a Greenhouse that will grow herbs over time from seeds planted, and provides all of the benefits of an Incense Candle. Requires a Campfire nearby. \r\n\r\nMay be placed over an Incense Candle to replace it.\r\n All camping features share a cooldown of $1308027d.", description = "Piazza una Serra che coltiva nel tempo le erbe dai semi piantati e fornisce tutti i benefici di una Candela d'incenso. Richiede un Falò nelle vicinanze. \r\n\r\nPuò essere piazzata sopra una Candela d'incenso per sostituirla.\r\n Tutte le strutture da accampamento condividono un tempo di recupero di $1308027d." },
    [1307251] = { en = "Ignites an incense candle that allows you and others sitting nearby to gain $?$PL<14[2]?$PL<28[6]?$PL<42[12]?$PL<56[18][$1229513s1] increased Intellect, exclusive with Arcane Intellect.\r\n\r\nRequires a Campfire nearby. All camping features share a cooldown of $1308027d.", description = "Accende una candela d'incenso che permette a te e agli altri seduti nelle vicinanze di ottenere $?$PL<14[2]?$PL<28[6]?$PL<42[12]?$PL<56[18][$1229513s1] in più all'Intelletto, incompatibile con Intelletto Arcano.\r\n\r\nRichiede un Falò nelle vicinanze. Tutte le strutture da accampamento condividono un tempo di recupero di $1308027d." },
    [1307252] = { en = "Builds a journeyman campfire that allows cooking and the placement of up to $s1 additional camp features. Players sitting or crafting nearby for $1229739d will gain benefits from other camp features.", description = "Costruisce un falò da apprendista esperto che consente di cucinare e piazzare fino a $s1 strutture da accampamento aggiuntive. I giocatori seduti o intenti a creare nelle vicinanze per $1229739d otterranno i benefici delle altre strutture da accampamento." },
    [1307254] = { en = "Erects a lodestone that allows you and others sitting nearby to gain $?$PL<12[12]?$PL<22[20]?$PL<32[32]?$PL<42[49]?$PL<52[67][$1230164s1] increased melee Attack Power, exclusive with Blessing of Might.\r\n\r\nRequires a Campfire nearby. All camping features share a cooldown of $1308027d.", description = "Erige una calamita che permette a te e agli altri seduti nelle vicinanze di ottenere $?$PL<12[12]?$PL<22[20]?$PL<32[32]?$PL<42[49]?$PL<52[67][$1230164s1] in più alla potenza d'attacco in mischia, incompatibile con Benedizione della Potenza.\r\n\r\nRichiede un Falò nelle vicinanze. Tutte le strutture da accampamento condividono un tempo di recupero di $1308027d." },
    [1307255] = { en = "Places a Loom usable for recipes that require it, and provides all the benefits of a Faction Banner. Requires a Campfire nearby. \r\n\r\nMay be placed over a Faction Banner to replace it. All camping features share a cooldown of $1308027d.", description = "Piazza un Telaio utilizzabile per le ricette che lo richiedono e fornisce tutti i benefici di uno Stendardo di fazione. Richiede un Falò nelle vicinanze. \r\n\r\nPuò essere piazzato sopra uno Stendardo di fazione per sostituirlo. Tutte le strutture da accampamento condividono un tempo di recupero di $1308027d." },
    [1307257] = { en = "Lay out Cookie's Feast that contains Stamina-boosting food. Requires a Cooking Fire nearby. All camping features share a cooldown of $1308027d.", description = "Prepara il Banchetto di Cookie, che contiene cibo che aumenta la Tempra. Richiede un Fuoco da cucina nelle vicinanze. Tutte le strutture da accampamento condividono un tempo di recupero di $1308027d." },
    [1307259] = { en = "Constructs a mana well that allows you and others sitting nearby to regenerate $?$PL<24[10]?$PL<34[15]?$PL<44[20]?$PL<54[24][$1230587s1] Mana every 5 sec, exclusive with Blessing of Wisdom.\n\nRequires a Campfire nearby. All camping features share a cooldown of $1308027d.", description = "Crea un pozzo di mana che permette a te e agli altri seduti nelle vicinanze di rigenerare $?$PL<24[10]?$PL<34[15]?$PL<44[20]?$PL<54[24][$1230587s1] mana ogni 5 s, incompatibile con Benedizione della Saggezza.\n\nRichiede un falò nelle vicinanze. Tutte le funzioni da campeggio condividono un tempo di recupero di $1308027d." },
    [1307261] = { en = "Places a Master Forge usable for recipes that require it, and provides all of the benefits of a Sharpening Wheel. Requires a Campfire nearby. \r\n\r\nMay be placed over a Sharpening Wheel to replace it. All camping features share a cooldown of $1308027d.", description = "Piazza una Forgia Maestra utilizzabile per le ricette che la richiedono e fornisce tutti i benefici di una Mola. Richiede un falò nelle vicinanze. \r\n\r\nPuò essere piazzata sopra una Mola per sostituirla. Tutte le funzioni da campeggio condividono un tempo di recupero di $1308027d." },
    [1307264] = { en = "Places a Molten Foundry usable for recipes that require it, and provides all the benefits of a Lodestone. Requires a Campfire nearby. \r\n\r\nMay be placed over a Lodestone to replace it. All camping features share a cooldown of $1308027d.", description = "Piazza una Fonderia Fusa utilizzabile per le ricette che la richiedono e fornisce tutti i benefici di una Pietra di Magnetite. Richiede un falò nelle vicinanze. \r\n\r\nPuò essere piazzata sopra una Pietra di Magnetite per sostituirla. Tutte le funzioni da campeggio condividono un tempo di recupero di $1308027d." },
    [1307265] = { en = "Places a Plague Doctor's Laboratory that contains healing potions, poultices, and provides all of the benefits of a First Aid Kit. Requires a Campfire nearby. \r\n\r\nMay be placed over a First Aid Kit to replace it. All camping features share a cooldown of $1308027d.", description = "Piazza un Laboratorio del Medico della Peste contenente pozioni curative e impiastri, e fornisce tutti i benefici di un Kit di Pronto Soccorso. Richiede un falò nelle vicinanze. \r\n\r\nPuò essere piazzato sopra un Kit di Pronto Soccorso per sostituirlo. Tutte le funzioni da campeggio condividono un tempo di recupero di $1308027d." },
    [1307266] = { en = "Summons a Reagent Bot that allows you and others nearby to purchase reagents. Requires a Campfire nearby. All camping features share a cooldown of $1308027d.", description = "Evoca un Bot dei Reagenti che permette a te e agli altri nelle vicinanze di acquistare reagenti. Richiede un falò nelle vicinanze. Tutte le funzioni da campeggio condividono un tempo di recupero di $1308027d." },
    [1307288] = { en = "Deal $s1 Shadow damage to the target and drains $s3 Mana. Deals $s2 times \r\nas much damage to Undead.", description = "Infligge $s1 danni da ombra al bersaglio e prosciuga $s3 mana. Infligge $s2 volte \r\ntanti danni ai Non Morti." },
    [1307315] = { en = "Chance on harmful spell cast to deal $1307288s1 Shadow damage to the target and drain $1307288s3 Mana. Deals $1307288s2 times as much damage to Undead.\r\n", description = "Quando lanci un incantesimo dannoso, hai una probabilità di infliggere $1307288s1 danni da ombra al bersaglio e prosciugare $1307288s3 mana. Infligge $1307288s2 volte tanti danni ai Non Morti.\r\n" },
    [1307334] = { en = "Increases healing done by up to $s1 and damage done by up to $s2 for all magical spells and effects while in Haunted areas.", description = "Aumenta le cure effettuate fino a $s1 e i danni inflitti fino a $s2 con tutti gli incantesimi ed effetti magici nelle aree infestate." },
    [1307385] = { en = "Summons a Repair Bot that allows you and others nearby to buy reagents and repair gear. Requires a Campfire nearby. \r\n\r\nMay be placed over a Reagent Bot to replace it. All camping features share a cooldown of $1308027d.", description = "Evoca un Bot di Riparazione che permette a te e agli altri nelle vicinanze di acquistare reagenti e riparare l'equipaggiamento. Richiede un falò nelle vicinanze. \r\n\r\nPuò essere piazzato sopra un Bot dei Reagenti per sostituirlo. Tutte le funzioni da campeggio condividono un tempo di recupero di $1308027d." },
    [1307386] = { en = "Places a Rock Garden that spawns a common mining node over time, and provides all the benefits of a Lodestone. Requires a Campfire nearby. \r\n\r\nMay be placed over a Lodestone to replace it. All camping features share a cooldown of $1308027d.", description = "Piazza un Giardino Roccioso che genera col tempo un comune filone minerario e fornisce tutti i benefici di una Pietra di Magnetite. Richiede un falò nelle vicinanze. \r\n\r\nPuò essere piazzato sopra una Pietra di Magnetite per sostituirlo. Tutte le funzioni da campeggio condividono un tempo di recupero di $1308027d." },
    [1307387] = { en = "Places a Seed Hybridizer that allows seeds to be multiplied or combined into rarer tiers, and provides all of the benefits of an Incense Candle. Requires a Campfire nearby. \r\n\r\nMay be placed over an Incense Candle to replace it.\r\n All camping features share a cooldown of $1308027d.", description = "Piazza un Ibridatore di Semi che permette di moltiplicare i semi o combinarli per ottenere categorie più rare e fornisce tutti i benefici di una Candela d'Incenso. Richiede un falò nelle vicinanze. \r\n\r\nPuò essere piazzato sopra una Candela d'Incenso per sostituirlo.\r\n Tutte le funzioni da campeggio condividono un tempo di recupero di $1308027d." },
    [1307391] = { en = "Places a Sewing Machine usable for recipes that require it, and provides all of the benefits of a Camp Tent. Requires a Campfire nearby. \r\n\r\nMay be placed over a Camp Tent to replace it. All camping features share a cooldown of $1308027d.", description = "Piazza una Macchina da Cucire utilizzabile per le ricette che la richiedono e fornisce tutti i benefici di una Tenda da Campeggio. Richiede un falò nelle vicinanze. \r\n\r\nPuò essere piazzata sopra una Tenda da Campeggio per sostituirla. Tutte le funzioni da campeggio condividono un tempo di recupero di $1308027d." },
    [1307392] = { en = "Constructs a sharpening wheel that grants you and others sitting nearby $?$PL<24[6]?$PL<38[11]?$PL<52[20][$1230172s1] increased Strength, exclusive with Strength of Earth Totem.\r\n\r\nRequires a Campfire nearby. All camping features share a cooldown of $1308027d.", description = "Crea una mola che conferisce a te e agli altri seduti nelle vicinanze $?$PL<24[6]?$PL<38[11]?$PL<52[20][$1230172s1] forza aggiuntiva, incompatibile con il Totem della Forza della Terra.\r\n\r\nRichiede un falò nelle vicinanze. Tutte le funzioni da campeggio condividono un tempo di recupero di $1308027d." },
    [1307393] = { en = "Places a Spinning Wheel that allows the creation of certain reagents, and provides all the benefits of a Faction Banner. Requires a Campfire nearby. \r\n\r\nMay be placed over a Faction Banner to replace it. All camping features share a cooldown of $1308027d.", description = "Piazza un Arcolaio che permette di creare determinati reagenti e fornisce tutti i benefici di uno Stendardo di Fazione. Richiede un falò nelle vicinanze. \r\n\r\nPuò essere piazzato sopra uno Stendardo di Fazione per sostituirlo. Tutte le funzioni da campeggio condividono un tempo di recupero di $1308027d." },
    [1307395] = { en = "Places a Tanning Rack that allows the creation of certain reagents, and provides all of the benefits of a Camp Tent. Requires a Campfire nearby. \r\n\r\nMay be placed over a Camp Tent to replace it. All camping features share a cooldown of $1308027d.", description = "Piazza un Cavalletto da Concia che permette di creare determinati reagenti e fornisce tutti i benefici di una Tenda da Campeggio. Richiede un falò nelle vicinanze. \r\n\r\nPuò essere piazzato sopra una Tenda da Campeggio per sostituirlo. Tutte le funzioni da campeggio condividono un tempo di recupero di $1308027d." },
    [1307396] = { en = "Places a Toxin Study that contains healing potions, anti-venom, and provides all of the benefits of a First Aid Kit. Requires a Campfire nearby. \r\n\r\nMay be placed over a First Aid Kit to replace it.\r\n All camping features share a cooldown of $1308027d.", description = "Piazza uno Studio dei Tossici contenente pozioni curative e antiveleni, e fornisce tutti i benefici di un Kit di Pronto Soccorso. Richiede un falò nelle vicinanze. \r\n\r\nPuò essere piazzato sopra un Kit di Pronto Soccorso per sostituirlo.\r\n Tutte le funzioni da campeggio condividono un tempo di recupero di $1308027d." },
    [1307397] = { en = "Places a Trapper's Workbench containing 1 trap, and provides all the benefits of a Camp Chair. Requires a Campfire nearby. \r\n\r\nMay be placed over a Camp Chair to replace it.\r\n\r\n All camping features share a cooldown of $1308027d.", description = "Piazza un Banco da Lavoro del Trapper contenente 1 trappola e fornisce tutti i benefici di una Sedia da Campeggio. Richiede un falò nelle vicinanze. \r\n\r\nPuò essere piazzato sopra una Sedia da Campeggio per sostituirlo.\r\n\r\n Tutte le funzioni da campeggio condividono un tempo di recupero di $1308027d." },
    [1307400] = { en = "Wrath critical strikes extend the duration of your Insect Swarm on the target by ${$s1/1000} sec. Against Beasts, this duration is extended by an additional ${$s2/1000} sec.", description = "I colpi critici di Ira prolungano di ${$s1/1000} s la durata del tuo Sciame d'Insetti sul bersaglio. Contro le Bestie, la durata viene prolungata di altri ${$s2/1000} s." },
    [1307426] = { en = "$@spelldesc1307423", description = "$@spelldesc1307423" },
    [1307508] = { en = "When struck in combat inflicts $s1 Nature and $1307509s1 Arcane damage to the attacker.", description = "Quando subisci un colpo in combattimento, infliggi $s1 danni da natura e $1307509s1 danni arcani all'attaccante." },
    [1307519] = { en = "Call upon nature's protection for $d. The first enemy to strike you with a melee attack becomes Rooted for $1307520d.", description = "Invoca la protezione della natura per $d. Il primo nemico che ti colpisce con un attacco in mischia viene Immobilizzato per $1307520d." },
    [1307644] = { en = "Melee attacks from enemies have a chance to refresh your Flame Blast cooldown.", description = "Gli attacchi in mischia dei nemici hanno una probabilità di azzerare il tempo di recupero della tua Esplosione di Fiamma." },
    [1307694] = { en = "[DNT] Suffer $s1% maximum health in damage every $t1 sec. Cannot kill the target.\r\n\r\nThis is a debug spell.", description = "[DNT] Subisci danni pari al $s1% della salute massima ogni $t1 s. Non può uccidere il bersaglio.\r\n\r\nQuesto è un incantesimo di debug." },
    [1307696] = { en = "Deal $s1 Nature damage to the target. Deals $s2 times as much damage to Dragonkin and Winged enemies.", description = "Infligge $s1 danni da natura al bersaglio. Infligge $s2 volte tanti danni ai Draghi e ai nemici alati." },
    [1307760] = { en = "Strength increased by $1307762s1 while carrying a full inventory.", description = "Forza aumentata di $1307762s1 mentre trasporti un inventario pieno." },
    [1307762] = { en = "Increases Strength by $s1 while your inventory is full.", description = "Aumenta la forza di $s1 quando l'inventario è pieno." },
    [1307791] = { en = "$s1 Health restored.", description = "$s1 salute ripristinata." },
    [1307792] = { en = "Restores $1305426s1 Health when you kill a Dragonkin that gives experience. This effect cannot occur more than once every $proccooldown sec.", description = "Ripristina $1305426s1 salute quando uccidi un Drago che fornisce esperienza. Questo effetto può verificarsi al massimo una volta ogni $proccooldown s." },
    [1307940] = { en = "Deal $s1 Holy damage to the target. Deals $s2 times as much damage to Undead and Demons.", description = "Infligge $s1 danni sacri al bersaglio. Infligge $s2 volte tanti danni ai Non Morti e ai Demoni." },
    [1308020] = { en = "Increases your effective stealth level by ${$s1/5}. This effect is doubled at Night.", description = "Aumenta il tuo livello effettivo di furtività di ${$s1/5}. Questo effetto raddoppia di notte." },
    [1308022] = { en = "Increases your effective stealth level by ${$s1/5} in Forest and Grassland areas.", description = "Aumenta il tuo livello effettivo di furtività di ${$s1/5} nelle aree boschive e prative." },
    [1308023] = { en = "Increases healing done by up to $s1 and damage done by up to $s2 for all magical spells and effects. This effect is doubled during the Day.", description = "Aumenta le cure effettuate fino a $s1 e i danni inflitti fino a $s2 con tutti gli incantesimi ed effetti magici. Questo effetto raddoppia di giorno." },
    [1308117] = { en = "Fill the crate with any bundle from the following list:", description = "Riempi la cassa con un qualsiasi pacco dal seguente elenco:" },
    [1308118] = { en = "Increases healing received by up to $s1 for $d.", description = "Aumenta le cure ricevute fino a $s1 per $d." },
    [1308128] = { en = "Chance on harmful spellcast to deal $1308132s1 Nature or Arcane damage. Deals $s1 times as much damage to Elves.", description = "Quando lanci un incantesimo dannoso, hai una probabilità di infliggere $1308132s1 danni da natura o arcani. Infligge $s1 volte tanti danni agli Elfi." },
    [1308131] = { en = "Deals $s1 Nature damage. Deals $1308128s1 times as much damage to Elves.", description = "Infligge $s1 danni da natura. Infligge $1308128s1 volte tanti danni agli Elfi." },
    [1308132] = { en = "Deals $s1 Arcane damage. Deals $1308128s1 times as much damage to Elves.", description = "Infligge $s1 danni arcani. Infligge $1308128s1 volte tanti danni agli Elfi." },
    [1308177] = { en = "Vulnerable to Amberhall's Soulstone.", description = "Vulnerabile alla Pietra dell'Anima di Amberhall." },
    [1308250] = { en = "Receive Cenarius' Gift for $d.", description = "Ricevi il Dono di Cenarius per $d." },
    [1308283] = { en = "Right Click to summon and dismiss your Shadowgale Squirrel.", description = "Clicca col tasto destro per evocare e congedare il tuo Scoiattolo di Shadowgale." },
    [1308351] = { en = "Increases damage and healing done by up to $s1 for all magical spells and effects. This effect is doubled in Snowy areas.", description = "Aumenta i danni inflitti e le cure effettuate fino a $s1 con tutti gli incantesimi ed effetti magici. Questo effetto raddoppia nelle aree innevate." },
    [1308377] = { en = "Use at the Ambermill Leyline Focus to create the Tome of Dalaran.", description = "Usa presso il Focalizzatore della Linea di Ley di Ambermill per creare il Tomo di Dalaran." },
    [1308463] = { en = "Split the target in two, causing $o1 Shadow damage over $d. Deals $s2 times as much damage if applied while in front of the target.", description = "Divide il bersaglio in due, infliggendo $o1 danni da ombra in $d. Infligge $s2 volte tanti danni se applicato di fronte al bersaglio." },
    [1308473] = { en = "The caster coats their weapons in a noxious poison causing their weapon attacks to have a chance of inflicting $s1 additional Nature damage.", description = "Il lanciatore ricopre le proprie armi con un veleno nocivo, facendo sì che i suoi attacchi con le armi abbiano una probabilità di infliggere $s1 danni aggiuntivi da natura." },
    [1308474] = { en = "$@spelldesc1308473", description = "$@spelldesc1308473" },
    [1308516] = { en = "Improves your chance to get a critical strike by ${$s1}.1%. This effect is doubled in Snowy areas.", description = "Aumenta la probabilità di mettere a segno un colpo critico di ${$s1}.1%. Questo effetto raddoppia nelle aree innevate." },
    [1308520] = { en = "Movement speed increased by $s1% in Forest and Grassland areas.", description = "Velocità di movimento aumentata del $s1% nelle aree boschive e prative." },
    [1308527] = { en = "$@spelldesc1307423", description = "$@spelldesc1307423" },
    [1308531] = { en = "Restores $s1 Mana per 5 sec in Forest and Grassland areas.", description = "Ripristina $s1 mana ogni 5 s nelle aree boschive e prative." },
    [1308764] = { en = "Strength increased by $s1 in Mountainous areas.", description = "Forza aumentata di $s1 nelle aree montuose." },
    [1308769] = { en = "Increases your chance to Block attacks with a shield by ${$s1/5}.1%. This effect is doubled in Mountainous areas.", description = "Aumenta la probabilità di bloccare gli attacchi con uno scudo di ${$s1/5}.1%. Questo effetto raddoppia nelle aree montuose." },
    [1308816] = { en = "Improves your chance to get a critical strike by ${$s1/14}.1%. This effect is doubled while in or on Water.", description = "Aumenta del ${$s1/14}.1% la probabilità di infliggere un colpo critico. Questo effetto raddoppia mentre sei in acqua o sulla sua superficie." },
    [1308836] = { en = "Gain the ability to display the \"Bloodsail Admiral\" title on this character as long as you remain in good standing with the Bloodsail Buccaneers.", description = "Ottieni la capacità di mostrare il titolo \"Ammiraglio dei Bloodsail\" con questo personaggio, finché mantieni una buona reputazione con i Bloodsail Buccaneers." },
    [1308870] = { en = "Right Click to summon and dismiss your weevil.", description = "Clic destro per evocare e congedare il tuo tonchio." },
    [1308913] = { en = "Your melee attacks have a chance to grant mana.", description = "I tuoi attacchi in mischia hanno una probabilità di conferire mana." },
    [1308917] = { en = "Remove $s1 Disarm effect from target ally.", description = "Rimuove l'effetto Disarmo $s1 dall'alleato bersaglio." },
    [1308939] = { en = "Fire Nova damage extends the duration of your Flame Shock on the target by ${$s1/1000} sec. Against Beasts, this duration is extended by an additional ${$s2/1000} sec.", description = "I danni di Fire Nova estendono di ${$s1/1000} sec. la durata del tuo Flame Shock sul bersaglio. Contro le Bestie, la durata è estesa di altri ${$s2/1000} sec." },
    [1309005] = { en = "Deal $s2 Frost damage and slow movement speed by $s1% for $d. Strikes up to ${$x2-1} additional nearby enemies, may strike the original target multiple times.", description = "Infligge $s2 danni da Gelo e riduce la velocità di movimento del $s1% per $d. Colpisce fino a ${$x2-1} nemici aggiuntivi nelle vicinanze e può colpire più volte il bersaglio originale." },
    [1309054] = { en = "Stealth to sneak around. Can only be used when out of combat. Lasts $d.", description = "Furtività per aggirare i nemici. Può essere usata solo fuori dal combattimento. Dura $d." },
    [1309062] = { en = "Shred damage extends the duration of your Rake on the target by ${$s1/1000} sec. Against Demons, this duration is extended by an additional ${$s2/1000} sec.", description = "I danni di Shred estendono di ${$s1/1000} sec. la durata del tuo Rake sul bersaglio. Contro i Demoni, la durata è estesa di altri ${$s2/1000} sec." },
    [1309072] = { en = "Inflicts $1309071s1 Fire damage every $t1 sec to units within $1309071a1 yds.", description = "Infligge $1309071s1 danni da Fuoco ogni $t1 sec. alle unità entro $1309071a1 m." },
    [1309191] = { en = "Deal $s1 Arcane damage to the target. Deals $s2 times as much damage if the target is casting.", description = "Infligge $s1 danni Arcani al bersaglio. Infligge danni pari a $s2 volte tanto se il bersaglio sta lanciando un incantesimo." },
    [1309208] = { en = "Summons and dismisses a rideable prideclaw.", description = "Evoca e congeda un prideclaw cavalcabile." },
    [1309241] = { en = "Increases healing done by up to $s1 and damage done by up to $s2 for all magical spells and effects. When you have not moved for $s3 sec, this effect is doubled.", description = "Aumenta le cure effettuate fino a $s1 e i danni inflitti fino a $s2 per tutti gli incantesimi e gli effetti magici. Se non ti muovi per $s3 sec., questo effetto raddoppia." },
    [1309283] = { en = "Increases backwards run speed by $s1% for $d1.", description = "Aumenta la velocità di corsa all'indietro del $s1% per $d1." },
    [1309318] = { en = "Increases Attack Power by $s1 for $d. This effect is doubled against Demons.", description = "Aumenta la Potenza d'Attacco di $s1 per $d. Questo effetto raddoppia contro i Demoni." },
    [1309320] = { en = "Harmful spell casts against Demons have a chance to deal $1309321s1 Shadowflame damage.", description = "Gli incantesimi offensivi lanciati contro i Demoni hanno una probabilità di infliggere $1309321s1 danni d'Ombrofuoco." },
    [1309322] = { en = "Melee and ranged attacks against Demons have a chance to deal $1309321s1 Shadowflame damage.", description = "Gli attacchi in mischia e a distanza contro i Demoni hanno una probabilità di infliggere $1309321s1 danni d'Ombrofuoco." },
    [1309369] = { en = "Movement speed increased by $s1% in Silverpine Forest and Hillsbrad Foothills.", description = "La velocità di movimento aumenta del $s1% nella Foresta di Silverpine e nelle Colline di Hillsbrad." },
    [1309405] = { en = "Summons and dismisses a rideable bear.", description = "Evoca e congeda un orso cavalcabile." },
    [1309420] = { en = "Right Click to summon and dismiss your [PH] Pachimara.", description = "Clic destro per evocare e congedare il tuo [PH] Pachimara." },
    [1309422] = { en = "Increases the damage dealt by your Stormstrike ability by $m1%.", description = "Aumenta i danni inflitti dalla tua abilità Stormstrike del $m1%." },
    [1309423] = { en = "Right Click to summon and dismiss your Galestrider Chick.", description = "Clic destro per evocare e congedare il tuo Galestrider Chick." },
    [1309442] = { en = "Increases the critical strike chance of your Lightning Bolt spell by $m1%.", description = "Aumenta la probabilità di colpo critico del tuo incantesimo Lightning Bolt del $m1%." },
    [1309539] = { en = "Increases the critical strike chance of your Healing Wave and Lesser Healing Wave spells by $m1%.", description = "Aumenta la probabilità di colpo critico dei tuoi incantesimi Healing Wave e Lesser Healing Wave del $m1%." },
    [1309549] = { en = "You have a $s1% chance to resist Fear.", description = "Hai una probabilità del $s1% di resistere alla Paura." },
    [1309550] = { en = "Your attacks have a chance to Wax, dealing $1319378s1 Arcane damage or Wane, granting $1319382s1 Strength for $1319382d.", description = "I tuoi attacchi hanno una probabilità di applicare Wax, infliggendo $1319378s1 danni Arcani, oppure Wane, conferendo $1319382s1 Forza per $1319382d." },
    [1309551] = { en = "Increases Fire damage taken by $s1% and movement speed by $s2% for $d.", description = "Aumenta i danni da Fuoco subiti del $s1% e la velocità di movimento del $s2% per $d." },
    [1309618] = { en = "Summons your own portable Windwell for $d.", description = "Evoca un Windwell portatile personale per $d." },
    [1309631] = { en = "Increases your Spirit by $m1%.", description = "Aumenta il tuo Spirito del $m1%." },
    [1309678] = { en = "[NYI]Grants you a shield which absorbs up to $s1 damage over $d. Fire damage is reduced by $s2% while the shield is active.", description = "[NYI]Ti conferisce uno scudo che assorbe fino a $s1 danni per $d. I danni da Fuoco sono ridotti del $s2% finché lo scudo è attivo." },
    [1309685] = { en = "Reach into the bag and hope for the best.", description = "Infila la mano nella borsa e spera per il meglio." },
    [1309718] = { en = "If an enemy strikes the imbiber, the attacker is struck by a swift axe, pinning them to the ground temporarily.", description = "Se un nemico colpisce chi ha ingerito la sostanza, l'attaccante viene colpito da un'ascia fulminea, che lo inchioda temporaneamente al suolo." },
    [1309765] = { en = "Spell hits have a chance to increase your wand attack speed.", description = "I colpi degli incantesimi hanno una probabilità di aumentare la velocità d'attacco della tua bacchetta." },
    [1309788] = { en = "Bewitch the target Beast, reducing the damage it does to you by $s1%.", description = "Ammalia la Bestia bersaglio, riducendo del $s1% i danni che ti infligge." },
    [1309823] = { en = "Silences a nearby enemy, preventing them from casting spells for $d.", description = "Silenzia un nemico nelle vicinanze, impedendogli di lanciare incantesimi per $d." },
    [1309950] = { en = "Reduces the mana cost of your Devouring Plague by $s1%.\r\n\r\nTargets that die while Devouring Plague is active spreads it, jumping to a nearby enemy within $s2 yards for the remaining duration.\r\n", description = "Riduce del $s1% il costo in mana di Devouring Plague.\r\n\r\nI bersagli che muoiono mentre Devouring Plague è attivo lo diffondono: l'effetto salta a un nemico vicino entro $s2 m e continua per la durata rimanente.\r\n" },
    [1309969] = { en = "Your Smite and Penance spells deal $m1% increased damage to targets afflicted with your Holy Fire.", description = "I tuoi incantesimi Smite e Penance infliggono il $m1% di danni in più ai bersagli affetti dal tuo Holy Fire." },
    [1310041] = { en = "Research the magical arts with the help of a library.", description = "Studia le arti magiche con l'aiuto di una biblioteca." },
    [1310076] = { en = "Increases Shadow Word: Death's critical strike chance on targets at or below $s2% health by $s1%.", description = "Aumenta del $s1% la probabilità di colpo critico di Shadow Word: Death sui bersagli con salute pari o inferiore al $s2%." },
    [1310077] = { en = "Increases spell Holy damage by up to $s1 for $d.", description = "Aumenta fino a $s1 i danni sacri degli incantesimi per $d." },
    [1310133] = { en = "Spread the ceremonial incense.", description = "Spargi l'incenso cerimoniale." },
    [1310167] = { en = "Launches a sawblade at the target, dealing $s1 damage and causing them to bleed for $o2damage over$d.", description = "Lancia una lama circolare contro il bersaglio, infliggendo $s1 danni e facendolo sanguinare per $o2damage nell'arco di $d." },
    [1310168] = { en = "Launches a sawblade at the target, dealing $1310167s1 damage and causing them to bleed for $1310167o2 damage over $1310167d.", description = "Lancia una lama circolare contro il bersaglio, infliggendo $1310167s1 danni e facendolo sanguinare per $1310167o2 danni nell'arco di $1310167d." },
    [1310181] = { en = "Unholster your Replica Ironforge Air Rifle for a friendly shootout.", description = "Estrai la tua Replica Ironforge Air Rifle per una sparatoria amichevole." },
    [1310185] = { en = "You retain up to $?s12295[${$m1+$12295m1}][$m1] Rage when you change Stances.", description = "Quando cambi Posizione, conservi fino a $?s12295[${$m1+$12295m1}][$m1] punti Rabbia." },
    [1310222] = { en = "A brutal attack that deals $s2% weapon damage. Deals an additional ${$s2*$s3}% weapon damage against Giants, Dragonkin, and mounted targets. Mounted targets are dismounted.", description = "Attacco brutale che infligge il $s2% dei danni dell'arma. Infligge un ulteriore ${$s2*$s3}% dei danni dell'arma contro Giganti, Draghi e bersagli in sella. I bersagli in sella vengono disarcionati." },
    [1310236] = { en = "Increases your maximum Rage by ${$m1/10}.", description = "Aumenta la tua Rabbia massima di ${$m1/10}." },
    [1310285] = { en = "Transforms a random enemy within $R1 yards into a satyr for $D sec. They're forced to speak demonic, and their casting speed is reduced by $S4%.", description = "Trasforma un nemico casuale entro $R1 m in un satiro per $D sec. È costretto a parlare demoniaco e la sua velocità di lancio è ridotta del $S4%." },
    [1310315] = { en = "Causes your Whirlwind to also strike with your off-hand weapon, and reduces the Rage cost of your Cleave ability by ${$m2/-10}.\r\n", description = "Fa sì che Whirlwind colpisca anche con l'arma nella mano secondaria e riduce di ${$m2/-10} il costo in Rabbia della tua abilità Cleave.\r\n" },
    [1310316] = { en = "Grants you a $m1% chance to generate ${$23602m1/10} Rage when you Dodge or Parry while a shield is equipped.", description = "Ti conferisce una probabilità del $m1% di generare ${$23602m1/10} punti Rabbia quando schivi o pari un attacco con uno scudo equipaggiato." },
    [1310317] = { en = "Your Charge ability is now usable while in Defensive Stance.", description = "La tua abilità Carica è ora utilizzabile in Posizione difensiva." },
    [1310318] = { en = "Generate ${$1310318m1/10} Rage when you Block.", description = "Genera ${$1310318m1/10} rabbia quando blocchi." },
    [1310496] = { en = "Reduces the cooldown of your Trap and Deterrence abilities by $m%.", description = "Riduce il tempo di recupero delle tue abilità Trappola e Dissuasione del $m%." },
    [1310532] = { en = "Your attacks against targets with Hunter's Mark have a $s1% chance to activate your Mongoose Bite for $5302d.", description = "I tuoi attacchi contro i bersagli con Marchio del Cacciatore hanno una probabilità del $s1% di attivare il tuo Morso della mangusta per $5302d." },
    [1310533] = { en = "Your Mongoose Bite also causes the target to Bleed for damage over $1310536d equal to $s1% of the damage done by Mongoose Bite.", description = "Il tuo Morso della mangusta fa inoltre Sanguinare il bersaglio, infliggendo danni periodici per $1310536d pari al $s1% dei danni inflitti da Morso della mangusta." },
    [1310594] = { en = "Collects a plains water sample.", description = "Raccoglie un campione d'acqua delle pianure." },
    [1310612] = { en = "Increases your pet's chance to Dodge by $s1% and decreases the time between your pet's attacks by $s2%. Lasts $d.", description = "Aumenta del $s1% la probabilità che il tuo famiglio schivi e riduce del $s2% l'intervallo tra gli attacchi del tuo famiglio. Dura $d." },
    [1310627] = { en = "Increases your melee critical strike damage by $s1% and your offhand weapon damage by $s2%.", description = "Aumenta del $s1% i danni dei tuoi colpi critici in mischia e del $s2% i danni della tua arma secondaria." },
    [1310655] = { en = "Causes the imbiber to be less detectable by creatures in Winterspring for $d. Only functions in Winterspring.", description = "Rende chi la beve meno individuabile dalle creature a Winterspring per $d. Funziona solo a Winterspring." },
    [1310661] = { en = "Increased the damage of your Serpent Sting ability by $s1%, reduces the cooldown of your Viper Sting ability by ${$m2/-1000} sec, and increases the duration of your Scorpid Sting ability by ${$m3/1000} sec.", description = "Aumenta del $s1% i danni della tua abilità Morso del serpente, riduce di ${$m2/-1000} sec il tempo di recupero della tua abilità Puntura di vipera e aumenta di ${$m3/1000} sec la durata della tua abilità Puntura dello scorpione." },
    [1310681] = { en = "Inject Hissing Serum into the system above Othmar's body.", description = "Inietta il Siero sibilante nell'impianto sopra il corpo di Othmar." },
    [1310703] = { en = "Finishing move that increases the damage of your Poisons by $m2% and your chance to apply Poisons by $m4%.  Lasts longer per combo point:\r\n   1 point  : 9 seconds\r\n   2 points: 12 seconds\r\n   3 points: 15 seconds\r\n   4 points: 18 seconds\r\n   5 points: 21 seconds", description = "Mossa risolutiva che aumenta i danni dei tuoi Veleni del $m2% e la probabilità di applicare Veleni del $m4%. Dura più a lungo per ogni punto combo:\r\n   1 punto  : 9 secondi\r\n   2 punti: 12 secondi\r\n   3 punti: 15 secondi\r\n   4 punti: 18 secondi\r\n   5 punti: 21 secondi" },
    [1310707] = { en = "Instantly attacks with both weapons for $1310706s2% weapon damage plus an additional ${$1310706m1*$1310706m2/100} with each weapon. Damage increased by $m4% against Poisoned targets. Awards $m1 Combo $LPoint:Points;.", description = "Attacca istantaneamente con entrambe le armi, infliggendo il $1310706s2% dei danni dell'arma più altri ${$1310706m1*$1310706m2/100} con ciascuna arma. I danni aumentano del $m4% contro i bersagli avvelenati. Fornisce $m1 $Lpunto:punti combo;." },
    [1310709] = { en = "Increases the damage of your Eviscerate ability against targets afflicted with your Deadly Poison by $m1% per application.", description = "Aumenta del $m1% i danni della tua abilità Eviscerazione contro i bersagli affetti dal tuo Veleno mortale per ogni applicazione." },
    [1310711] = { en = "Reduces the Energy cost of your Eviscerate ability by $m1.", description = "Riduce di $m1 il costo in energia della tua abilità Eviscerazione." },
    [1310721] = { en = "When your Rupture ability deals periodic damage, the Energy cost of your next Hemorrhage or Backstab ability within $1310723d is reduced by $1310723s1, stacking up to $1310723u times.", description = "Quando la tua abilità Lacerazione infligge danni periodici, il costo in energia della tua prossima abilità Emorragia o Agguato entro $1310723d si riduce di $1310723s1, cumulabile fino a $1310723u volte." },
    [1310728] = { en = "Your Sinister Strike, Ghostly Strike, and Hemorrhage abilities cause $m1% more damage against targets below $m2% health.", description = "Le tue abilità Attacco sinistro, Colpo spettrale ed Emorragia infliggono il $m1% di danni in più ai bersagli con meno del $m2% di salute." },
    [1310735] = { en = "Reduces the Mana cost of your Seal spells by $s1%, and when you replace your Seal of Command, Seal of Righteousness, Seal of Fury, or Seal of Justice with a different Seal, gain an Echo of that Seal. Your next melee attack applies the replaced Seal's effects, consuming the Echo.", description = "Riduce del $s1% il costo in mana dei tuoi incantesimi Sigillo e, quando sostituisci Sigillo del comando, Sigillo della rettitudine, Sigillo della furia o Sigillo della giustizia con un Sigillo diverso, ottieni un'Eco di quel Sigillo. Il tuo prossimo attacco in mischia applica gli effetti del Sigillo sostituito e consuma l'Eco." },
    [1310893] = { en = "Combine with the rest of the pieces to create the whole.", description = "Combina questo oggetto con gli altri pezzi per creare il set completo." },
    [1310897] = { en = "Grants you immunity to Silence and Interrupt effects.  Lasts $d.", description = "Ti rende immune agli effetti di Silenzio e Interruzione. Dura $d." },
    [1310902] = { en = "Reduces the cooldown of your Holy Strike ability by ${$m1/-1000} sec.", description = "Riduce di ${$m1/-1000} sec il tempo di recupero della tua abilità Colpo sacro." },
    [1310905] = { en = "Gives your Holy spells $m1% increased damage against the first $20924s3 enemies that enter your Consecration.", description = "Aumenta del $m1% i danni dei tuoi incantesimi sacri contro i primi $20924s3 nemici che entrano nella tua Consacrazione." },
    [1310909] = { en = "The caster's next Holy Shock on this target will active Light's Vigil, healing the target and their party for $1310912s1.", description = "Il prossimo Shock sacro dell'incantatore su questo bersaglio attiverà Vigilanza della Luce, curando il bersaglio e il suo gruppo di $1310912s1." },
    [1310910] = { en = "Detonates for $1310914s1 Holy damage when struck by the caster's Holy Shock.", description = "Esplode infliggendo $1310914s1 danni sacri quando viene colpito dallo Shock sacro dell'incantatore." },
    [1310911] = { en = "Applies Light's Vigil to the target for $1310909d. Your next Holy Shock cast on them triggers no cooldown and causes enemy targets to suffer $1310914s1 Holy damage and refund $s2% of Light's Vigil's Mana cost, or allied targets to heal their party for $1310912s1.  The Paladin may only have one Light's Vigil active per party.", description = "Applica Vigilanza della Luce al bersaglio per $1310909d. Il tuo prossimo Shock sacro lanciato su di lui non ha tempo di recupero e infligge $1310914s1 danni sacri ai bersagli nemici e restituisce il $s2% del costo in mana di Vigilanza della Luce, oppure cura il gruppo dei bersagli alleati di $1310912s1. Il paladino può avere attiva una sola Vigilanza della Luce per gruppo." },
    [1310925] = { en = "Restores $m1% of your maximum Mana when you Block.", description = "Ripristina il $m1% del tuo mana massimo quando blocchi." },
    [1310949] = { en = "Increases the critical effect chance of your Shadow spells by $s1%.", description = "Aumenta del $s1% la probabilità di effetto critico dei tuoi incantesimi d'ombra." },
    [1310994] = { en = "Finishes the remaining cooldown on your Judgement ability and reduces the Mana cost of your next Judgement by $s1%.", description = "Azzera il tempo di recupero residuo della tua abilità Giudizio e riduce del $s1% il costo in mana del tuo prossimo Giudizio." },
    [1311015] = { en = "When activated, this ability grants you an absorb shield equal to $s1% of your maximum health for $d.  Applies Forbearance for $25771d. Cannot be cast while Forbearance is active.", description = "Quando viene attivata, questa abilità ti conferisce uno scudo di assorbimento pari al $s1% della tua salute massima per $d. Applica Indulgenza per $25771d. Non può essere lanciata mentre Indulgenza è attiva." },
    [1311022] = { en = "Increases your chance to hit with your off-hand weapon by $s1%.", description = "Aumenta del $s1% la probabilità di colpire con la tua arma secondaria." },
    [1311034] = { en = "Increases the threat generated by your Holy Strike ability $m1%. While Righteous Fury is active, Holy Strike also reduces your damage taken by $m2% for $1311033d.", description = "Aumenta del $m1% la minaccia generata dalla tua abilità Colpo sacro. Quando Furia virtuosa è attiva, Colpo sacro riduce anche i danni subiti del $m2% per $1311033d." },
    [1311074] = { en = "Gives your Judgement ability a $m1% chance to return $m2% of the Mana cost of the judged seal.", description = "La tua abilità Giudizio ha una probabilità del $m1% di restituire il $m2% del costo in mana del Sigillo giudicato." },
    [1311077] = { en = "Judging restores a portion of the Judged Seal's Mana cost.", description = "Il Giudizio ripristina una parte del costo in mana del Sigillo giudicato." },
    [1311083] = { en = "Increases all damage dealt by $m1%. Increased by an additional $m2% against Demon and Undead targets.", description = "Aumenta del $m1% tutti i danni inflitti. L'aumento è del $m2% aggiuntivo contro demoni e non morti." },
    [1311084] = { en = "Increases your spell damage and healing by up to $m1% of your Intellect.", description = "Aumenta i danni e le cure dei tuoi incantesimi fino a un massimo pari al $m1% della tua Intelletto." },
    [1311085] = { en = "Reduces the cast time of your Hammer of Wrath by ${$m1/-1000}.1 sec, and reduces all threat you generate by $m2% while Righteous Fury is not active.", description = "Riduce di ${$m1/-1000}.1 sec il tempo di lancio del tuo Martello dell'ira e riduce del $m2% tutta la minaccia generata quando Furia virtuosa non è attiva." },
    [1311087] = { en = "Increases the damage of your Holy Strike ability by $m1% and causes it to refresh all Judgement effects on the target.", description = "Aumenta del $m1% i danni della tua abilità Colpo sacro e fa aggiornare tutti gli effetti di Giudizio sul bersaglio." },
    [1311590] = { en = "Applies Light's Vigil to the target for $1311593d. Your next Holy Shock cast on them triggers no cooldown and causes enemy targets to suffer $1311592s1 Holy damage and refund $s2% of Light's Vigil's Mana cost, or allied targets to heal their party for $1311591s1.  The Paladin may only have one Light's Vigil active per party.", description = "Applica Vigilanza della Luce al bersaglio per $1311593d. Il tuo prossimo Shock sacro lanciato su di lui non ha tempo di recupero e infligge $1311592s1 danni sacri ai bersagli nemici e restituisce il $s2% del costo in mana di Vigilanza della Luce, oppure cura il gruppo dei bersagli alleati di $1311591s1. Il paladino può avere attiva una sola Vigilanza della Luce per gruppo." },
    [1311593] = { en = "The caster's next Holy Shock on this target will activate Light's Vigil, healing the target and their party for $131159s1.", description = "Il prossimo Shock sacro dell'incantatore su questo bersaglio attiverà Vigilanza della Luce, curando il bersaglio e il suo gruppo di $131159s1." },
    [1311594] = { en = "Detonates for $1311592s1 Holy damage when struck by the caster's Holy Shock.", description = "Esplode infliggendo $1311592s1 danni sacri quando viene colpito dallo Shock sacro dell'incantatore." },
    [1311595] = { en = "Applies Light's Vigil to the target for $1311597d. Your next Holy Shock cast on them triggers no cooldown and causes enemy targets to suffer $1311598s1 Holy damage and refund $s2% of Light's Vigil's Mana cost, or allied targets to heal their party for $1311596s1.  The Paladin may only have one Light's Vigil active per party.", description = "Applica Vigilanza della Luce al bersaglio per $1311597d. Il tuo prossimo Shock sacro lanciato su di lui non ha tempo di recupero e infligge $1311598s1 danni sacri ai bersagli nemici e restituisce il $s2% del costo in mana di Vigilanza della Luce, oppure cura il gruppo dei bersagli alleati di $1311596s1. Il paladino può avere attiva una sola Vigilanza della Luce per gruppo." },
    [1311597] = { en = "The caster's next Holy Shock on this target will activate Light's Vigil, healing the target and their party for $1311596s1.", description = "Il prossimo Shock sacro dell'incantatore su questo bersaglio attiverà Vigilanza della Luce, curando il bersaglio e il suo gruppo di $1311596s1." },
    [1311599] = { en = "Detonates for $1311598s1 Holy damage when struck by the caster's Holy Shock.", description = "Esplode infliggendo $1311598s1 danni sacri quando viene colpito dallo Shock sacro dell'incantatore." },
    [1311606] = { en = "Blasts the target with Holy energy, causing $1311604s1 Holy damage to an enemy, or $1311605s1 healing to an ally.", description = "Colpisce il bersaglio con energia sacra, infliggendo $1311604s1 danni sacri a un nemico oppure curando un alleato di $1311605s1." },
    [1311649] = { en = "Fills the Paladin with divine fury for $d, causing melee attacks to deal an additional $1311647s1 Holy damage. While a shield is equipped, each attack also grants an absorb shield equal to $m2% of the Holy damage dealt.  Only one Seal can be active on the Paladin at any one time.\r\n\r\nUnleashing this Seal's energy causes $1311650s1 Holy damage to an enemy and taunts the target to attack you for $20232d.", description = "Colma il paladino di furia divina per $d, facendo infliggere agli attacchi in mischia altri $1311647s1 danni sacri. Con uno scudo equipaggiato, ogni attacco conferisce anche uno scudo di assorbimento pari al $m2% dei danni sacri inflitti. Il paladino può avere attivo un solo Sigillo alla volta.\r\n\r\nScatenare l'energia di questo Sigillo infligge $1311650s1 danni sacri a un nemico e provoca il bersaglio, costringendolo ad attaccarti per $20232d." },
    [1311656] = { en = "Fills the Paladin with divine fury for $d, causing melee attacks to deal an additional $1311654s1 Holy damage. While a shield is equipped, each attack also grants an absorb shield equal to $m2% of the Holy damage dealt.  Only one Seal can be active on the Paladin at any one time.\r\n\r\nUnleashing this Seal's energy causes $1311655s1 Holy damage to an enemy and taunts the target to attack you for $20232d.", description = "Colma il paladino di furia divina per $d, facendo infliggere agli attacchi in mischia altri $1311654s1 danni sacri. Con uno scudo equipaggiato, ogni attacco conferisce anche uno scudo di assorbimento pari al $m2% dei danni sacri inflitti. Il paladino può avere attivo un solo Sigillo alla volta.\r\n\r\nScatenare l'energia di questo Sigillo infligge $1311655s1 danni sacri a un nemico e provoca il bersaglio, costringendolo ad attaccarti per $20232d." },
    [1311895] = { en = "Movement speed increased by $s1% in Hyjal.", description = "Velocità di movimento aumentata del $s1% a Hyjal." },
    [1311947] = { en = "Summons forth a Conjured Arcane Elemental to assist the caster.", description = "Evoca un Elementale arcano evocato in aiuto dell'incantatore." },
    [1312052] = { en = "Deals $443265o1 Fire damage over $443265d to target Demon or Beast and Roots them in place for $d.  Damage caused may interrupt the effect.", description = "Infligge $443265o1 danni da fuoco in $443265d al demone o alla bestia bersaglio e lo immobilizza per $d. I danni inflitti possono interrompere l'effetto." },
    [1312176] = { en = "Blast the target with the fires of a forge, inflicting $s1 Fire damage.", description = "Colpisce il bersaglio con le fiamme di una forgia, infliggendo $s1 danni da fuoco." },
    [1312233] = { en = "Open to receive level appropriate goods and equipment to aid your travels.\r\n\r\nEnsure you have ample inventory space before opening. Excess items can be retrieved from a mailbox.", description = "Si apre per ricevere beni ed equipaggiamento adeguati al livello, utili durante i tuoi viaggi.\r\n\r\nAssicurati di avere spazio sufficiente nell'inventario prima di aprirlo. Gli oggetti in eccesso possono essere ritirati da una cassetta postale." },
    [1312330] = { en = "Smite your target with the power of the holy spring, inflicting $s1 Holy damage.", description = "Colpisci il bersaglio con il potere della fonte sacra, infliggendo $s1 danni da Sacro." },
    [1312643] = { en = "Cultivate a nearby herb to grow a duplicate you can harvest without requiring Herbalism skill.", description = "Coltiva un'erba vicina per farne crescere un duplicato che puoi raccogliere senza abilità di Erbalismo." },
    [1312670] = { en = "Returns you to $?pc923[Orgrimmar][Stormwind]. Single-use.", description = "Ti riporta a $?pc923[Orgrimmar][Stormwind]. Utilizzabile una sola volta." },
    [1312698] = { en = "Restores $s1% health.", description = "Ripristina il $s1% della salute." },
    [1312870] = { en = "Inflicts $s1 Nature damage to enemies within $a1 yards of the current target.", description = "Infligge $s1 danni da Natura ai nemici entro $a1 metri dal bersaglio attuale." },
    [1312934] = { en = "Fire Blast critical strike chance increased by $s1%.", description = "Probabilità di colpo critico di Esplosione di Fuoco aumentata del $s1%." },
    [1313374] = { en = "Melt the key at a forge for $s1 Bronze Bars.", description = "Fondi la chiave presso una forgia per ottenere $s1 lingotti di bronzo." },
    [1314011] = { en = "Smash the target for $s1 damage.", description = "Fracassa il bersaglio infliggendo $s1 danni." },
    [1314040] = { en = "Strike the target with a Flaming Shell, inflicting $s1 Fire damage every 3 sec for 9 sec.", description = "Colpisci il bersaglio con un Proiettile Fiammeggiante, infliggendo $s1 danni da Fuoco ogni 3 sec per 9 sec." },
    [1314065] = { en = "Movement speed increased by $s1% while mounted. This effect does not stack with similar effects.", description = "Velocità di movimento aumentata del $s1% in sella. Questo effetto non si cumula con effetti simili." },
    [1314069] = { en = "Blast the enemy inflicting $s1 Fire damage.", description = "Fai esplodere il nemico, infliggendo $s1 danni da Fuoco." },
    [1314103] = { en = "When Seal of Fury's shield is fully absorbed, restore $m1 Mana, increased by $m2% per level the attacker is above you, up to ${$m2*$m3}%.", description = "Quando lo scudo di Sigillo della Furia viene assorbito completamente, ripristina $m1 Mana, aumentato del $m2% per ogni livello di cui l'attaccante ti supera, fino a un massimo di ${$m2*$m3}%." },
    [1314104] = { en = "When Seal of Fury's shield is fully absorbed, restore $PL Mana, increased by $1314103m2% per level the attacker is above you, up to ${$1314103m2*$1314103m3}%.\r\n", description = "Quando lo scudo di Sigillo della Furia viene assorbito completamente, ripristina $PL Mana, aumentato del $1314103m2% per ogni livello di cui l'attaccante ti supera, fino a un massimo di ${$1314103m2*$1314103m3}%.\r\n" },
    [1314120] = { en = "Right Click to summon and dismiss your condor hatchling.", description = "Clicca con il tasto destro per evocare e congedare il tuo cucciolo di condor." },
    [1314143] = { en = "$@spelldesc16939", description = "$@spelldesc16939" },
    [1314274] = { en = "Unleash a shadow bolt volley at all nearby targets, inflicting $s1 damage to each enemy struck.", description = "Scatena una raffica di dardi d'ombra contro tutti i bersagli vicini, infliggendo $s1 danni a ogni nemico colpito." },
    [1314281] = { en = "Fire damage dealt to all enemies in target area.", description = "Danni da Fuoco inflitti a tutti i nemici nell'area bersaglio." },
    [1314364] = { en = "Summons a swarm of spiders that will protect you for $d.", description = "Evoca uno sciame di ragni che ti proteggerà per $d." },
    [1314412] = { en = "Absorbs $s1 Fire damage for $d. Damage absorbed heals you for the same amount.", description = "Assorbe $s1 danni da Fuoco per $d. I danni assorbiti ti curano della stessa quantità." },
    [1314415] = { en = "Fire damage absorbed Heals the user.", description = "I danni da Fuoco assorbiti curano chi li subisce." },
    [1314828] = { en = "Improves your chance to get a critical strike by ${$s1}.1%. This effect is doubled at Night.", description = "Aumenta la probabilità di infliggere un colpo critico di ${$s1}.1%. Questo effetto raddoppia di notte." },
    [1314842] = { en = "Blessed by the Great Cat Spirit.", description = "Benedetto dal Grande Spirito Felino." },
    [1314888] = { en = "Strike your target with a Poisonous Sting, inflicting $s1 damage every 3 sec for $d1.", description = "Colpisci il bersaglio con un Pungiglione Velenoso, infliggendo $s1 danni ogni 3 sec per $d1." },
    [1315077] = { en = "Chance on melee attack to lash the target, inflicting $s1 Shadow damage.", description = "Probabilità, con un attacco in mischia, di colpire il bersaglio, infliggendo $s1 danni da Ombra." },
    [1315080] = { en = "Increases mount speed by $s1% in Eastern and Western Plaguelands.", description = "Aumenta la velocità della cavalcatura del $s1% nelle Terre Infette Orientali e Occidentali." },
