    [1315212] = { en = "Burn in the scarlet flames to return you to $z. Speak to an Innkeeper in a different place to change your home location.", description = "Brucia tra le fiamme scarlatte per tornare a $z. Parla con un locandiere in un altro luogo per cambiare la tua dimora." },
    [1315213] = { en = "Create a Scarlet Hearthstone.", description = "Crea una Pietra del Ritorno Scarlatta." },
    [1315237] = { en = "Breathes putrid rot and decay, inflicting $S1 nature damage to all players within $r yards.", description = "Emette un putrido soffio di marciume e decomposizione, infliggendo $S1 danni da Natura a tutti i giocatori entro $r metri." },
    [1315267] = { en = "Right Click to summon and dismiss your Tallstrider Hatchling.", description = "Clicca con il tasto destro per evocare e congedare il tuo cucciolo di tallstrider." },
    [1315330] = { en = "Intellect increased by $s1 at night.", description = "Intelletto aumentato di $s1 di notte." },
    [1315339] = { en = "Increases intellect by $s1 at night.", description = "Aumenta l'intelletto di $s1 di notte." },
    [1315408] = { en = "Blessed by the Great Windborne Cat Spirit.", description = "Benedetto dal Grande Spirito Felino Alato." },
    [1315557] = { en = "Charms the target, preventing all actions for up to $d.  Any damage caused will remove the effect. Only works against Humanoids.", description = "Ammalia il bersaglio, impedendogli ogni azione per un massimo di $d. Qualsiasi danno subito rimuoverà l'effetto. Funziona solo sugli umanoidi." },
    [1315778] = { en = "Increases mount speed by $s1% in Winterspring.", description = "Aumenta la velocità della cavalcatura del $s1% a Fontefredda." },
