    [1315969] = { en = "Your spells pierce $s1 Magical Resistances. Gain an additional $1315971s1 Spell Piercing in Forest and Grassland areas.", description = "I tuoi incantesimi penetrano $s1 resistenze magiche. Ottieni un ulteriore valore di penetrazione degli incantesimi pari a $1315971s1 nelle aree forestali e prative." },
    [1315989] = { en = "Increases all Resistances by $s1. Gain an additional $1315990s1 to all Resistances in Forest and Grassland areas.", description = "Aumenta tutte le resistenze di $s1. Ottieni un ulteriore valore di $1315990s1 a tutte le resistenze nelle aree forestali e prative." },
    [1316039] = { en = "Sear your target's flesh dealing $s1 Fire damage.", description = "Brucia la carne del bersaglio, infliggendo $s1 danni da Fuoco." },
