    [1316051] = { en = "Increases all Resistances by $s1. Gain an additional $1316052s1 to all Resistances in Forest and Grassland areas.", description = "Aumenta tutte le resistenze di $s1. Ottieni un ulteriore valore di $1316052s1 a tutte le resistenze nelle aree forestali e prative." },
    [1316057] = { en = "Increases all Resistances by $s1. Gain an additional $1316058s1 to all Resistances in Forest and Grassland areas.", description = "Aumenta tutte le resistenze di $s1. Ottieni un ulteriore valore di $1316058s1 a tutte le resistenze nelle aree forestali e prative." },
    [1316101] = { en = "Increases the duration of your Repentance by ${$m1/1000} sec.", description = "Aumenta la durata del tuo Pentimento di ${$m1/1000} sec." },
    [1316319] = { en = "All ranged auto-attacks conjure an icy bolt to blast your current target, inflicting $29502s1 Frost damage.", description = "Tutti gli attacchi automatici a distanza evocano un dardo gelido che colpisce il bersaglio attuale, infliggendo $29502s1 danni da Gelo." },
    [1316346] = { en = "Slice the target's ankle, slowing movement speed by $s1% for $d.", description = "Squarcia la caviglia del bersaglio, riducendone la velocità di movimento del $s1% per $d." },
    [1316382] = { en = "Kicks up dust inflicting $s1 Physical damage to enemies within $a1 yds and reducing hit chance with attacks by $s2%.", description = "Solleva polvere che infligge $s1 danni fisici ai nemici entro $a1 m e riduce del $s2% la probabilità di colpire con gli attacchi." },
    [1316387] = { en = "$@spelldesc1316388", description = "$@spelldesc1316388" },
    [1316388] = { en = "Has a chance to affect the current target with $@spellname1316387 reducing the targets Spirit and Stamina by $1316387s1% for $1316387d.\r\n", description = "Ha una probabilità di colpire il bersaglio attuale con $@spellname1316387, riducendo del $1316387s1% lo Spirito e la Tempra del bersaglio per $1316387d.\r\n" },
    [1316480] = { en = "Entangles nearby enemies in roots, inflicting $s2  Nature damage every $t2 sec. and immobilizing it for up to $d.", description = "Intrappola i nemici vicini con radici, infliggendo $s2 danni da Natura ogni $t2 sec. e immobilizzandoli per un massimo di $d." },
    [1316555] = { en = "Slams the opponent, causing Physical damage.", description = "Colpisce violentemente l'avversario, infliggendo danni fisici." },
