    [1316595] = { en = "$@spelldesc1247432", description = "$@spelldesc1247432" },
    [1316596] = { en = "$@spelldesc1247432", description = "$@spelldesc1247432" },
    [1316597] = { en = "$@spelldesc1247437", description = "$@spelldesc1247437" },
    [1316598] = { en = "$@spelldesc1247442", description = "$@spelldesc1247442" },
    [1316697] = { en = "Tears the target apart from within, dealing $s1 Shadow damage every $t sec and increasing the damage they take from your other Shadow damage over time effects by $s2%. Lasts $d.", description = "Lacerà il bersaglio dall'interno, infliggendo $s1 danni da ombra ogni $t sec e aumentando del $s2% i danni che subisce dai tuoi altri effetti di danno periodico da ombra. Dura $d." },
    [1316778] = { en = "Right Click to summon and dismiss your Minimule.", description = "Clic destro per evocare e congedare il tuo Minimule." },
    [1316794] = { en = "$@spelldesc1270940", description = "$@spelldesc1270940" },
    [1316847] = { en = "Summons a wolf that will protect you for $d.", description = "Evoca un lupo che ti proteggerà per $d." },
    [1316872] = { en = "Unlocked in a future patch.", description = "Disponibile in una patch futura." },
    [1316991] = { en = "Healing for $s1 every $1316992t2 sec. for $1316992d.", description = "Cura di $s1 ogni $1316992t2 sec. per $1316992d." },
    [1316993] = { en = "Dealing $s1 Holy damage every $1316994t2 sec.", description = "Infligge $s1 danni da Sacro ogni $1316994t2 sec." },
    [1316995] = { en = "Launches a volley of holy light at the target, causing $1316993s1 Holy damage to an enemy, or $1316991s1 healing to an ally, instantly and every $402261t2 sec for $402261d.", description = "Scaglia una raffica di luce sacra contro il bersaglio, infliggendo $1316993s1 danni da Sacro a un nemico oppure curando un alleato di $1316991s1, istantaneamente e ogni $402261t2 sec per $402261d." },
    [1317006] = { en = "When you cast a healing spell, gain Mana equal to $m1% of the base cost of the spell if your previous heal was a different spell.", description = "Quando lanci un incantesimo di cura, ottieni Mana pari al $m1% del costo base dell'incantesimo se la tua cura precedente era un incantesimo diverso." },
    [1317007] = { en = "When you cast a healing spell, regain a portion of its base cost if your previous heal was a different spell.", description = "Quando lanci un incantesimo di cura, recuperi una parte del suo costo base se la tua cura precedente era un incantesimo diverso." },
    [1317039] = { en = "Chance on melee swing to become Angry, increasing Strength by $1317040s1 for $1317040d.", description = "Possibilità a ogni attacco in mischia di diventare Furioso, aumentando la Forza di $1317040s1 per $1317040d." },
    [1317170] = { en = "Summons a Fire Elemental to aid the caster in battle for $d.", description = "Evoca un Elementale del Fuoco per aiutare chi lancia l'incantesimo in battaglia per $d." },
    [1317256] = { en = "To be added in a future update.", description = "Da aggiungere in un aggiornamento futuro." },
    [1317257] = { en = "A powerful kick that deals $s2% melee weapon damage and increases movement speed by $s3% for $d.", description = "Un potente calcio che infligge danni pari al $s2% dei danni dell'arma da mischia e aumenta la velocità di movimento del $s3% per $d." },
    [1317268] = { en = "Inflicts $s1 Holy damage to targets in a $a1 yard radius. May occasionally backfire and imbue targets with the power of the Light.", description = "Infligge $s1 danni da Sacro ai bersagli entro un raggio di $a1 iarde. A volte può ritorcersi contro e infondere nei bersagli il potere della Luce." },
    [1317269] = { en = "Bless the grenade with the Light.", description = "Benedice la granata con la Luce." },
    [1317272] = { en = "Fills the target with holy spirit for $d, granting each melee attack  additional Holy damage. ", description = "Colma il bersaglio di spirito sacro per $d, conferendo a ogni attacco in mischia danni da Sacro aggiuntivi. " },
    [1317279] = { en = "Transmutes a bar of Heavy Thorium and a Fel Crystal into a Legionite Bar.", description = "Trasmuta un lingotto di Torio Pesante e un Cristallo Vil in un Lingotto di Legionite." },
    [1317288] = { en = "Stuns target for $d. Naga are stunned for $1317288d and refund $1317288s2% of the cooldown.", description = "Stordisce il bersaglio per $d. Le Naga vengono stordite per $1317288d e rimborsano il $1317288s2% del tempo di recupero." },
    [1317432] = { en = "Deal $s1 Fire damage. Deals $s2 times as much damage to Earth Elementals, Fire Elementals, and Mountain Giants.", description = "Infligge $s1 danni da Fuoco. Infligge un danno pari a $s2 volte tanto agli Elementali della Terra, agli Elementali del Fuoco e ai Giganti della Montagna." },
    [1317441] = { en = "Increases all Resistances by $s1. Gain an additional $1317442s1 to all Resistances in Forest and Grassland areas.", description = "Aumenta tutte le Resistenze di $s1. Ottieni altri $1317442s1 a tutte le Resistenze nelle aree boschive e nelle praterie." },
    [1317443] = { en = "Your spells pierce $s1 Magical Resistances. Gain an additional $1317444s1 Spell Piercing in Forest and Grassland areas.", description = "I tuoi incantesimi perforano $s1 Resistenze magiche. Ottieni altri $1317444s1 di Perforazione incantesimi nelle aree boschive e nelle praterie." },
    [1317446] = { en = "You have a small chance to find additional ore when mining Ooze Covered Thorium Veins.", description = "Hai una piccola probabilità di trovare minerale aggiuntivo estraendo Filoni di Torio Ricoperti di Melma." },
    [1317486] = { en = "Movement speed increased by $s1% in Dustwallow Marsh and Swamp of Sorrows.", description = "La velocità di movimento aumenta del $s1% a Palude di Dustwallow e nelle Paludi Grigie." },
    [1317583] = { en = "Your attacks have a high chance to poison the target for $s1 Nature damage every $t1 sec for $d.", description = "I tuoi attacchi hanno un'alta probabilità di avvelenare il bersaglio, infliggendo $s1 danni da Natura ogni $t1 sec per $d." },
    [1317604] = { en = "Removes all Bleed, Disease, and Poison effects.", description = "Rimuove tutti gli effetti di Sanguinamento, Malattia e Veleno." },
    [1317605] = { en = "Turn on the lights of Dalaran.", description = "Accende le luci di Dalaran." },
    [1317695] = { en = "Teaches Beast Training, Feed Pet and Revive Pet.", description = "Insegna Addestramento bestie, Nutri famiglio e Rianima famiglio." },
    [1317740] = { en = "Finds the nearest treasure chest, if one is nearby. Only outdoors.", description = "Trova il forziere del tesoro più vicino, se ce n'è uno nei paraggi. Solo all'aperto." },
    [1318024] = { en = "Place a Compact Critter Carrier for $d that allows Hunters in your group to access their stabled pets.", description = "Posiziona un Trasportino compatto per bestiole per $d, che consente ai Cacciatori del tuo gruppo di accedere ai loro animali custoditi nella stalla." },
    [1318034] = { en = "Thrown attacks explode on impact, causing $1318031s1 Fire damage to nearby enemies.", description = "Gli attacchi a distanza esplodono all'impatto, infliggendo $1318031s1 danni da Fuoco ai nemici vicini." },
